#!/usr/bin/env bash
# JVM test for the generator core: compiles app.webgen.core + TestMain and
# produces two samples signed by the apksig library (NOT the apksigner
# tool) with a key generated by SelfSignedCert into a scratch dir
# (persistence/reuse check included):
#   sample-wiki-by-generator-code.apk  - all permission toggles ON
#   sample-perm-off.apk                - all permission toggles OFF
set -euo pipefail
ROOT="$HOME/workspace/web2apk"
export JAVA_HOME="$ROOT/tools/jdk"
export PATH="$JAVA_HOME/bin:$PATH"
APKSIGNER_JAR="$ROOT/tools/sdk/build-tools/34.0.0/lib/apksigner.jar"
WORK="$ROOT/build-generator-test"
rm -rf "$WORK"
mkdir -p "$WORK/classes" "$WORK/keys"
javac -encoding UTF-8 -cp "$APKSIGNER_JAR" -d "$WORK/classes" \
  "$ROOT"/generator-app/app/src/main/java/app/webgen/core/*.java \
  "$ROOT/generator-app/test/TestMain.java"
java -cp "$WORK/classes:$APKSIGNER_JAR" TestMain \
  "$ROOT/template.apk" "$ROOT/sample_icon.png" "$WORK/keys" \
  "$ROOT/sample-wiki-by-generator-code.apk" "$ROOT/sample-perm-off.apk"
